/**
 * OpenAI Node - Version 1.7
 * Discriminator: resource=audio, operation=translate
 */


interface Credentials {
  openAiApi: CredentialReference;
}

/** Translates audio into text in English */
export type LcOpenAiV17AudioTranslateParams = {
  resource: 'audio';
  operation: 'translate';
/**
 * Name of the binary property which contains the audio file in one of these formats: flac, mp3, mp4, mpeg, mpga, m4a, ogg, wav, or webm
 * @hint The name of the input field containing the binary file data to be processed
 * @default data
 */
    binaryPropertyName?: string | Expression<string>;
/**
 * Options
 * @default {}
 */
    options?: {
    /** Output Randomness (Temperature)
     * @default 0
     */
    temperature?: number | Expression<number>;
  };
};

export interface LcOpenAiV17AudioTranslateSubnodeConfig {
  tools?: ToolInstance[];
  memory?: MemoryInstance;
}

export type LcOpenAiV17AudioTranslateNode = {
  type: '@n8n/n8n-nodes-langchain.openAi';
  version: 1.7;
  isTrigger: true;
  config: NodeConfig<LcOpenAiV17AudioTranslateParams> & { credentials?: Credentials } & { subnodes?: LcOpenAiV17AudioTranslateSubnodeConfig };
};